import json
from itertools import permutations

def solve_puzzle():
    houses = [1, 2, 3]

    names = ['Eric', 'Arnold', 'Peter']
    smoothies = ['desert', 'watermelon', 'cherry']
    genres = ['science fiction', 'romance', 'mystery']

    solutions = []

    for name_perm in permutations(houses):
        name_to_house = dict(zip(names, name_perm))

        # Clue 5: Peter is in the first house.
        if name_to_house['Peter'] != 1:
            continue

        for genre_perm in permutations(houses):
            genre_to_house = dict(zip(genres, genre_perm))

            # Clue 2: Arnold is the person who loves mystery books.
            if name_to_house['Arnold'] != genre_to_house['mystery']:
                continue

            # Clue 3: The person who loves science fiction books is not in the first house.
            if genre_to_house['science fiction'] == 1:
                continue

            for smoothie_perm in permutations(houses):
                smoothie_to_house = dict(zip(smoothies, smoothie_perm))

                # Clue 4: The Desert smoothie lover is directly left of the person who loves mystery books.
                if smoothie_to_house['desert'] + 1 != genre_to_house['mystery']:
                    continue

                # Clue 1: The person who likes Cherry smoothies is somewhere to the left of the person who loves mystery books.
                if not (smoothie_to_house['cherry'] < genre_to_house['mystery']):
                    continue

                # Build house-based mappings
                house_to_name = {house: name for name, house in name_to_house.items()}
                house_to_smoothie = {house: sm for sm, house in smoothie_to_house.items()}
                house_to_genre = {house: gr for gr, house in genre_to_house.items()}

                # Construct solution rows
                rows = []
                for h in houses:
                    rows.append([str(h), house_to_name[h], house_to_smoothie[h], house_to_genre[h]])

                solutions.append(rows)

    # Assuming unique solution for the given puzzle
    if not solutions:
        raise ValueError("No solution found for the given puzzle constraints.")
    if len(solutions) > 1:
        # In case of multiple, choose the first deterministically
        rows = solutions[0]
    else:
        rows = solutions[0]

    result = {
        "solution": {
            "header": ["House", "Name", "Smoothie", "BookGenre"],
            "rows": rows
        }
    }
    return result

if __name__ == "__main__":
    print(json.dumps(solve_puzzle(), ensure_ascii=False))
